mapper.insert:
INSERT INTO identity_collision (workspace_id, company_identity_id, rebuilt_at)
SELECT collision.workspace_id, collision.identity_id, #{rebuiltAt}
FROM (
  SELECT ci.workspace_id,
         ci.id AS identity_id,
         COUNT(*) OVER (
           PARTITION BY ci.workspace_id, ci.kind, ci.normalized_value
         ) AS collision_size
  FROM company_identity ci
  JOIN company c
    ON c.workspace_id = ci.workspace_id
    AND c.id = ci.company_id
  WHERE ci.workspace_id = #{workspaceId}
) collision
WHERE collision.collision_size >= 2
ON DUPLICATE KEY UPDATE rebuilt_at = #{rebuiltAt}

mapper.select:
SELECT COUNT(*)
FROM identity_collision
WHERE workspace_id = #{workspaceId}

WITH visible_collision_members AS (
) SELECT record_type, kind, normalized_value, COUNT(*) AS collision_size, MAX(rebuilt_at) AS rebuilt_at FROM visible_collision_members
record_type = #{recordType} AND kind = #{kind}
GROUP BY record_type, kind, normalized_value HAVING COUNT(*) >= 2 ORDER BY record_type, kind, normalized_value LIMIT #{limit} OFFSET #{offset}

WITH visible_collision_members AS (

)
SELECT COUNT(*)
FROM (
  SELECT record_type, kind, normalized_value
  FROM visible_collision_members

    record_type = #{recordType}
    AND kind = #{kind}

  GROUP BY record_type, kind, normalized_value
  HAVING COUNT(*) >= 2
) collision_groups

WITH visible_collision_members AS (

),
sized_collision_members AS (
  SELECT record_type,
         kind,
         normalized_value,
         record_id,
         record_name,
         COUNT(*) OVER (
           PARTITION BY record_type, kind, normalized_value
         ) AS collision_size,
         ROW_NUMBER() OVER (
           PARTITION BY record_type, kind, normalized_value
           ORDER BY record_id
         ) AS member_rank
  FROM visible_collision_members
)
SELECT record_type, kind, normalized_value, record_id, record_name
FROM sized_collision_members
WHERE collision_size >= 2
  AND member_rank <= #{memberLimit}
  AND (

      (
        record_type = #{group.recordType}
        AND kind = #{group.kind}
        AND normalized_value = #{group.normalizedValue}
      )

  )
ORDER BY record_type, kind, normalized_value, record_id
